pub fn parse_num(s: &str) -> Option<f64> {
    let t = s.trim();
    if t.is_empty() {
        return None;
    }
    if !t.bytes().all(|c| c.is_ascii_digit() || matches!(c, b'.' | b'e' | b'E' | b'+' | b'-')) {
        return None;
    }
    t.parse::<f64>().ok()
}

pub fn fix15(x: f64) -> f64 {
    format!("{:.14e}", x).parse::<f64>().unwrap_or(x)
}

pub fn fmt_num(n: f64) -> String {
    if n == 0.0 {
        return "0".into();
    }
    let s = format!("{:.14e}", n);
    let (mant, exp) = s.split_once('e').unwrap();
    let exp: i32 = exp.parse().unwrap();
    let neg = mant.starts_with('-');
    let digits: String = mant.chars().filter(|c| c.is_ascii_digit()).collect();
    let digits = digits.trim_end_matches('0');
    let digits = if digits.is_empty() { "0" } else { digits };
    let body = if exp >= 15 || exp < -9 {
        let mut m = String::new();
        m.push_str(&digits[..1]);
        if digits.len() > 1 {
            m.push('.');
            m.push_str(&digits[1..]);
        }
        format!("{}E{}{:02}", m, if exp < 0 { '-' } else { '+' }, exp.abs())
    } else if exp >= 0 {
        let ip = exp as usize + 1;
        if digits.len() <= ip {
            let mut s = digits.to_string();
            s.push_str(&"0".repeat(ip - digits.len()));
            s
        } else {
            format!("{}.{}", &digits[..ip], &digits[ip..])
        }
    } else {
        format!("0.{}{}", "0".repeat((-exp - 1) as usize), digits)
    };
    if neg {
        format!("-{}", body)
    } else {
        body
    }
}

pub fn to_num(v: &Val) -> Result<f64, ErrK> {
    match v {
