        Val::Num(n) => Ok(*n),
        Val::Bool(b) => Ok(if *b { 1.0 } else { 0.0 }),
        Val::Str(s) => parse_num(s).ok_or(ErrK::Value),
        Val::Err(e) => Err(*e),
    }
}

pub fn to_text(v: &Val) -> String {
    match v {
        Val::Empty => String::new(),
        Val::Num(n) => fmt_num(*n),
        Val::Bool(b) => {
            if *b {
                "TRUE".into()
            } else {
                "FALSE".into()
            }
        }
        Val::Str(s) => s.to_string(),
        Val::Err(e) => e.text().to_string(),
    }
}

pub fn to_bool(v: &Val) -> Result<bool, ErrK> {
    match v {
        Val::Empty => Ok(false),
        Val::Num(n) => Ok(*n != 0.0),
        Val::Bool(b) => Ok(*b),
        Val::Str(s) => {
            let u = s.to_ascii_uppercase();
            if u == "TRUE" {
                Ok(true)
            } else if u == "FALSE" {
                Ok(false)
            } else {
                Err(ErrK::Value)
            }
        }
        Val::Err(e) => Err(*e),
    }
}

fn rank(v: &Val) -> u8 {
    match v {
        Val::Num(_) => 0,
        Val::Str(_) => 1,
        Val::Bool(_) => 2,
