        (Val::Str(a), Val::Str(b)) => {
            if wc && has_wild(a) {
                wild_eq(a, b)
            } else {
                a.to_lowercase() == b.to_lowercase()
            }
        }
        (Val::Bool(a), Val::Bool(b)) => a == b,
        _ => false,
    }
}

