fn col_index(s: &str) -> u32 {
    let mut col: u32 = 0;
    for ch in s.bytes() {
        if ch.is_ascii_alphabetic() {
            col = col * 26 + (ch.to_ascii_uppercase() - b'A' + 1) as u32;
        }
    }
    col.max(1) - 1
}

fn parse_ref_attr(r: &str) -> (u32, u32) {
