s=open(p).read()
# VLOOKUP approx
old="""                        match lk_cmp(&look, x) {
                            Some(Ordering::Less) | Some(Ordering::Equal) => found = Some(k),
                            Some(Ordering::Greater) => break,
                            None => {}
                        }"""
new="""                        match lk_cmp(&look, x) {
                            Some(Ordering::Greater) | Some(Ordering::Equal) => found = Some(k),
