new="""                        match lk_cmp(&look, x) {
                            Some(Ordering::Greater) | Some(Ordering::Equal) => res = Some(i),
                            Some(Ordering::Less) => break,
                            None => {}
                        }"""
assert s.count(old)==1; s=s.replace(old,new)
old="""                        match lk_cmp(&look, x) {
                            Some(Ordering::Greater) | Some(Ordering::Equal) => res = Some(i),
