input.command:
cd /workspace/submission && python3 -I - <<'EOF'
p='src/eval.rs'
s=open(p).read()
start=s.index("pub fn fmt_num(n: f64) -> String {")
end=s.index("pub fn to_num(v: &Val)")
new='''pub fn fmt_num(n: f64) -> String {
    if n == 0.0 {
        return "0".into();
    }
    let s = format!("{:e}", n);
    let (mant, exps) = s.split_once('e').unwrap();
    let mut exp: i32 = exps.parse().unwrap();
    let neg = mant.starts_with('-');
    let mut digs: Vec<u8> = mant.bytes().filter(|c| c.is_ascii_digit()).map(|c| c - b'0').collect();
    if digs.len() > 15 {
        let first = digs[15];
        let rest_nz = digs[16..].iter().any(|d| *d != 0);
        let mut keep: Vec<u8> = digs[..15].to_vec();
        let up = first > 5 || (first == 5 && (rest_nz || keep[14] % 2 == 1));
        if up {
            let mut i = 14;
            loop {
                if keep[i] == 9 {
                    keep[i] = 0;
                    if i == 0 {
                        keep.insert(0, 1);
                        keep.pop();
                        exp += 1;
                        break;
                    }
                    i -= 1;
                } else {
                    keep[i] += 1;
                    break;
                }
            }
        }
        digs = keep;
    }
    let mut ds: String = digs.iter().map(|d| (b'0' + d) as char).collect();
    while ds.len() > 1 && ds.ends_with('0') {
        ds.pop();
    }
    let digits = ds.as_str();
    let body = if exp >= 15 || exp < -9 {
        let mut m = String::new();
        m.push_str(&digits[..1]);
        if digits.len() > 1 {
            m.push('.');
            m.push_str(&digits[1..]);
        }
        format!("{}E{}{:03}", m, if exp < 0 { '-' } else { '+' }, exp.abs())
    } else if exp >= 0 {
        let ip = exp as usize + 1;
        if digits.len() <= ip {
            let mut s = digits.to_string();
            s.push_str(&"0".repeat(ip - digits.len()));
            s
        } else {
            format!("{}.{}", &digits[..ip], &digits[ip..])
        }
    } else {
        format!("0.{}{}", "0".repeat((-exp - 1) as usize), digits)
    };
    if neg {
        format!("-{}", body)
    } else {
        body
    }
}

'''
s=s[:start]+new+s[end:]
old='''        Val::Bool(b) => {
            if *b {
                "TRUE".into()
            } else {
                "FALSE".into()
            }
        }
        Val::Str(s) => s.to_string(),'''
assert s.count(old)==1
s=s.replace(old,'''        Val::Bool(b) => {
            if *b {
                "1".into()
            } else {
                "0".into()
            }
        }
        Val::Str(s) => s.to_string(),''')
open(p,'w').write(s)
EOF
./build.sh | tail -1; check-public --no-build 2>&1 | head -3 | cut -c1-300

