cd /task/public/books && python3 -I - <<'EOF'
import openpyxl, glob, re, collections
fmts=collections.Counter(); dates=collections.Counter()
for f in sorted(glob.glob('/task/public/books/*.xlsx')):
    wb=openpyxl.load_workbook(f)
    for ws in wb:
        for row in ws.iter_rows():
            for c in row:
                v=c.value
                if isinstance(v,str) and v.startswith('=') and 'TEXT(' in v:
                    for m in re.findall(r'TEXT\([^,]*,\s*("[^"]*")\)', v): fmts[m]+=1
                if isinstance(v,str) and v.startswith('=') and 'DATEDIF' in v:
                    for m in re.findall(r'"(\w+)"\)', v): dates[m]+=1
print(fmts.most_common(40)); print(dates)
EOF

